base=np.linspace(.5,8,80);ho_up=base+1;ho_dn=base-1;bdt_up=base*np.exp(.2);bdt_dn=base*np.exp(-.2);ax.plot(base,ho_up,label='Ho-Lee up: +1 point',color=ACCENT);ax.plot(base,ho_dn,label='Ho-Lee down: -1 point',color=ACCENT,ls='--');ax.plot(base,bdt_up,label='BDT up: multiplicative',color=GOOD);ax.plot(base,bdt_dn,label='BDT down: multiplicative',color=GOOD,ls='--');ax.axhline(0,color=INK,lw=1);ax.set_xlabel('Starting short rate (%)');ax.set_ylabel('Next-node rate (%)');ax.set_title('The models encode different shock geometry');ax.legend(fontsize=7)
